query:
-- Fix TX-1 runoff label to be cleaner
UPDATE house_races SET candidate1_name = 'Y. Prince / D. Alexander (D Runoff)'
WHERE state_code = 'TX' AND district = '1';

-- Fix TX-5 runoff label
UPDATE house_races SET candidate1_name = 'C. Hockett / R. Torres (D Runoff)'
WHERE state_code = 'TX' AND district = '5';

-- Fix TX-7 runoff label  
UPDATE house_races SET candidate2_name = 'A. Hale / T. Cohen (R Runoff)'
WHERE state_code = 'TX' AND district = '7';

-- Fix TX-9 runoff label
UPDATE house_races SET candidate2_name = 'A. Mealer / B. Cain (R Runoff)'
WHERE state_code = 'TX' AND district = '9';

-- TX-14: D runoff (Bartie vs Davis), no R candidate yet - fix label
UPDATE house_races SET candidate1_name = 'T. Bartie / R. Davis (D Runoff)'
WHERE state_code = 'TX' AND district = '14';

-- TX-16: Two R candidates means R primary runoff
UPDATE house_races SET status = 'Primary Runoff', candidate2_name = 'A. Bauman / M. Barraza (R Runoff)', candidate2_party = 'R', candidate1_name = NULL, candidate1_party = NULL
WHERE state_code = 'TX' AND district = '16';

-- TX-17: Two D candidates means D primary runoff
UPDATE house_races SET status = 'Primary Runoff', candidate1_name = 'M. Flores / C. Shepard (D Runoff)', candidate1_party = 'D', candidate2_name = NULL, candidate2_party = NULL
WHERE state_code = 'TX' AND district = '17';

-- TX-24: Two D candidates means D primary runoff
UPDATE house_races SET status = 'Primary Runoff', candidate1_name = 'K. Burge / T. Ware (D Runoff)', candidate1_party = 'D', candidate2_name = NULL, candidate2_party = NULL
WHERE state_code = 'TX' AND district = '24';

SELECT state_code, district, status, candidate1_name, candidate1_party, candidate2_name, candidate2_party 
FROM house_races WHERE state_code = 'TX' AND district IN ('1','5','7','9','14','16','17','24') ORDER BY CAST(district AS UNSIGNED);

